#!/bin/bash
# Flight Deck Desk installer v2 (vcge-lab PR #1). Written by Cornerstone (Team vCGE) 2026-10-26.
# What it does, and nothing else:
#  1. Checks the files packed below against their sha256; stops if anything changed since review.
#  2. Checks the live Flight Deck index.html is the reviewed live version (main e21e5b3 + the 10-24 "On vacation"
#     wording); stops without changing anything if it is not.
#  3. Backs up the live Flight Deck folder to portal/www.before-desk.
#  4. Adds portal/www/desk/ (Rules, Welcome, Copy-paste Inbox + config.js with the Google Client ID), the new
#     index.html (three Desk tiles, honest "only the Desk talks to Google" wording, live wording kept), and appends
#     two Desk tile style lines to the live portal.css (nothing else in it changes). Root-owned, 644.
#  5. Checks http://127.0.0.1:8080/ and /desk/ answer 200. No Caddy change, no service change, no reload.
# Undo: sudo rm -rf /srv/dataprojects/portal/www && sudo cp -a /srv/dataprojects/portal/www.before-desk /srv/dataprojects/portal/www
set -euo pipefail
WWW=/srv/dataprojects/portal/www
PAYLOAD_SHA=87850212931befcfd392dc45c87fa179dfd5e88d827a30653d76ab1e5f6cbb8a
LIVE_INDEX_SHA=20828d1029c32e2b759564adba280ee862f47c98170f817120c1d1da0ca3473c
[ "$(id -u)" = 0 ] || { echo "Run through vcge-lab-run (needs root)."; exit 1; }
[ -d "$WWW" ] || { echo "STOP: $WWW not found. Nothing changed."; exit 1; }
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
base64 -d > "$TMP/payload.tgz" <<'PAYLOAD'

PAYLOAD
echo "$PAYLOAD_SHA  $TMP/payload.tgz" | sha256sum -c --quiet - || { echo "STOP: packed files changed since review. Nothing changed."; exit 1; }
echo "$LIVE_INDEX_SHA  $WWW/index.html" | sha256sum -c --quiet - || { echo "STOP: live index.html is not the reviewed version. Nothing changed."; exit 1; }
[ -f "$WWW/portal.css" ] || { echo "STOP: live portal.css missing. Nothing changed."; exit 1; }
[ -e "$WWW.before-desk" ] && { echo "STOP: backup $WWW.before-desk already exists (installed before?). Nothing changed."; exit 1; }
cp -a "$WWW" "$WWW.before-desk"
mkdir "$TMP/x"; tar -xzf "$TMP/payload.tgz" -C "$TMP/x" --no-same-owner
install -d -o root -g root -m 755 "$WWW/desk"
for f in desk/index.html desk/desk.js desk/desk-core.js desk/desk.css desk/config.js index.html; do
  install -o root -g root -m 644 "$TMP/x/$f" "$WWW/$f"
done
grep -q '^\.tools\.desk ' "$WWW/portal.css" || printf '%s\n' '.tools.desk { margin: 0 0 6px; }' '.desk-note { color: var(--dim); font-size: .82rem; margin-bottom: 20px; }' >> "$WWW/portal.css"
for p in / /desk/ /desk/desk.js /desk/config.js /portal.css; do
  code=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:8080$p")
  echo "$p -> $code"; [ "$code" = 200 ] || { echo "CHECK FAILED on $p. Undo line is at the top of this script."; exit 1; }
done
echo "Desk installed. Open https://vcge-lab.tailfc4090.ts.net/desk/ . Backup: $WWW.before-desk"
